package com.primehr.security;
import com.primehr.integration.administrative.*; import org.junit.jupiter.api.Test; import org.springframework.security.access.AccessDeniedException; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class SuccessionFoundationPermissionGuardTest {
 @Test void actionAndAgencyScopeAreEnforced(){var client=mock(AdministrativeAuthorizationClient.class);var guard=new SuccessionFoundationPermissionGuard(client);when(client.resolve(SuccessionFoundationPermissionGuard.GOVERNANCE,"Bearer token")).thenReturn(permission(true,true,false,true,PermissionDataScope.AGENCY_WIDE));when(client.resolve(SuccessionFoundationPermissionGuard.COMMITTEE,"Bearer token")).thenReturn(permission(true,true,true,true,PermissionDataScope.ASSIGNED_RECORDS));assertThatCode(()->guard.require(SuccessionFoundationPermissionGuard.GOVERNANCE,PrimeHrAction.PUBLISH,"Bearer token")).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(SuccessionFoundationPermissionGuard.GOVERNANCE,PrimeHrAction.EDIT,"Bearer token")).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->guard.require(SuccessionFoundationPermissionGuard.COMMITTEE,PrimeHrAction.EDIT,"Bearer token")).isInstanceOf(AccessDeniedException.class);}
 private EffectiveFeaturePermission permission(boolean access,boolean add,boolean edit,boolean publish,PermissionDataScope scope){return new EffectiveFeaturePermission("feature",false,access,add,edit,false,publish,false,false,false,false,false,scope);}
}
